import type {ServerLicense} from '../types/server-licenses'

export interface LicenseExpirationStatus {
  isExpired: boolean
  isExpiringSoon: boolean // 0-7 days before expiration
  daysUntilExpiration: number
}

/**
 * Checks if a license is expired or expiring soon
 * @param license - The server license to check
 * @param currentDate - Optional current date for testing purposes
 * @returns Status object indicating expiration state
 */
export function getLicenseExpirationStatus(
  license: ServerLicense | undefined,
  currentDate: Date = new Date(),
): LicenseExpirationStatus {
  if (!license) {
    return {
      isExpired: false,
      isExpiringSoon: false,
      daysUntilExpiration: Infinity,
    }
  }

  const expiresAt = new Date(license.expires_at)
  const timeDiff = expiresAt.getTime() - currentDate.getTime()
  const daysUntilExpiration = Math.ceil(timeDiff / (1000 * 60 * 60 * 24))

  const isExpired = daysUntilExpiration < 0
  const isExpiringSoon = daysUntilExpiration >= 0 && daysUntilExpiration <= 7

  return {
    isExpired,
    isExpiringSoon,
    daysUntilExpiration,
  }
}
